import { useState } from "react";
import { Estrellas } from "./Estrellas.jsx";

const mensajes = ["", "Muy malo", "Malo", "Regular", "Bueno", "Excelente"];

export default function App() {
  const [nota, setNota] = useState(0);

  return (
    <main style={{ maxWidth: 420, margin: "2rem auto", fontFamily: "system-ui, sans-serif" }}>
      <h1>¿Qué tal tu pedido?</h1>
      <p>Califica tu experiencia con Pollería El Rancho.</p>
      <Estrellas total={5} onCambio={setNota} />
      <p>{nota ? `Tu nota: ${nota} de 5, ${mensajes[nota]}` : "Aún no calificas"}</p>
    </main>
  );
}
